mapper.select:
SELECT DISTINCT p.* FROM pur_yt_purchase p LEFT JOIN pur_yt_purchase_item pi ON p.id = pi.purchase_id LEFT JOIN sal_yt_order_sub sos ON sos.id = pi.order_sub_id left join sal_yt_order so on so.id = sos.order_id LEFT JOIN pro_yt_product pr ON pi.product_id = pr.id WHERE p.is_deleted = 0
AND p.code LIKE CONCAT('%', #{code}, '%')
AND (SELECT MIN(status) AS min_status FROM pur_yt_purchase_item WHERE purchase_id = p.id AND is_deleted = 0 and specification_id is not null ) = #{status}
AND (SELECT MIN(status) AS min_status FROM pur_yt_purchase_item WHERE purchase_id = p.id AND is_deleted = 0 and specification_id is not null ) > #{minStatus}
AND p.supplier_id = #{supplierId}
AND p.supplier_name LIKE CONCAT('%', #{supplierName}, '%')
AND p.order_platform_code = #{orderPlatformCode}
AND p.is_inbound_delivery = #{isInboundDelivery}
AND pr.code LIKE CONCAT('%', #{productCode}, '%')
AND sos.sub_code LIKE CONCAT('%', #{orderSubCode}, '%')
AND so.code LIKE CONCAT('%', #{orderCode}, '%')
AND p.delivery_time >= #{deliveryStartTime}
AND p.delivery_time <= #{deliveryEndTime}
ORDER BY p.submit_purchase_time DESC, p.create_time DESC

SELECT COUNT(*) > 0
FROM pur_yt_purchase
WHERE code = #{code}
AND is_deleted = 0

    AND id != #{excludeId}

SELECT DATE_FORMAT(p.create_time, '%Y-%m') AS month, SUM(pi.supplier_price * pi.number) AS amount FROM pur_yt_purchase p LEFT JOIN pur_yt_purchase_item pi ON p.id = pi.purchase_id WHERE p.supplier_id = #{supplierId} AND p.is_deleted = 0 AND pi.is_deleted = 0
AND p.create_time >= #{startTime}
AND p.create_time <= #{endTime}
GROUP BY DATE_FORMAT(p.create_time, '%Y-%m') ORDER BY month

SELECT pypc.name AS categoryName, SUM(pi.supplier_price * pi.number) AS amount FROM pur_yt_purchase p LEFT JOIN pur_yt_purchase_item pi ON p.id = pi.purchase_id LEFT JOIN pro_yt_product pyp ON pi.product_id = pyp.id LEFT JOIN pro_yt_product_category pypc ON pyp.category_id = pypc.id WHERE p.supplier_id = #{supplierId} AND p.is_deleted = 0 AND pi.is_deleted = 0 AND pyp.is_deleted = 0 AND pypc.is_deleted = 0
AND p.create_time >= #{startTime}
AND p.create_time <= #{endTime}
GROUP BY pypc.id, pypc.name ORDER BY amount DESC
